const roles=computed(()=>store.getters['user/permissions']||[]),allowed=computed(()=>props.active&&!!store.state.user.accessToken&&(props.governance?roles.value.includes('super_admin'):roles.value.some(r=>['admin','director','super_admin'].includes(r))));
const department=ref(props.departmentId),ward=ref(props.wardId),departments=ref([]),options=ref(null),status=ref(''),page=ref(1),items=ref([]),total=ref(0),loading=ref(false),error=ref(''),notice=ref(''),timezone=ref(''),dateFrom=ref(''),dateTo=ref(''),candidate=ref(null),editor=ref(null),formValid=ref(false),previewing=ref(false),saving=ref(false),detail=ref(null),detailOpen=ref(false),detailError=ref(''),reviewBasis=ref(''),revokeReason=ref(''),acting=ref(false),showFrozen=ref(false),showPublic=ref(false),sourceDetail=ref(null),sourceOpen=ref(false),sourceError=ref(''),sourcesOpen=ref(false);
