const auth=()=>supportCanonical([props.departmentId,props.wardId,props.governance,props.active,store.state.user.accessToken,store.state.user.username,roles.value]),query=()=>supportCanonical([department.value,ward.value,status.value,page.value]),ticket=()=>({epoch,auth:auth()}),current=t=>alive&&!paused&&allowed.value&&t.epoch===epoch&&t.auth===auth();
const period=computed(()=>({ward_id:ward.value,business_timezone:timezone.value,date_from:dateFrom.value,date_to:dateTo.value})),periodValid=computed(()=>bedSeriesPeriodValid(period.value)),canRecord=computed(()=>allowed.value&&bedPositive(department.value)&&bedPositive(ward.value)&&options.value?.department_id===department.value&&options.value.can_record===true&&options.value.wards.some(w=>w.ward_id===ward.value&&w.department_id===department.value)),canReview=computed(()=>allowed.value&&roles.value.includes('super_admin')&&detail.value?.can_review===true),revokeValid=computed(()=>!!revokeReason.value.trim()&&bedSeriesSchemaMatches('SeriesRevoke',{expected_revision:detail.value?.revision,reason:revokeReason.value}));
