function clearPreview(){previewSeq++;candidate.value=null;formValid.value=false;previewing.value=saving.value=false;sourceOpen.value=false;clearSource();}
function reset(){epoch++;catalogSeq++;optionsSeq++;listSeq++;clearPreview();clearDetail();detailOpen.value=sourcesOpen.value=false;department.value=props.departmentId;ward.value=props.wardId;departments.value=[];options.value=null;items.value=[];total.value=0;page.value=1;loading.value=false;timezone.value=dateFrom.value=dateTo.value=error.value=notice.value='';}
function unavailable(message){items.value=[];total.value=0;detailOpen.value=false;clearDetail();clearPreview();error.value=message||'当前病区访问或完整集合无法重新核对，已清除旧正文。';}
async function catalog(){const t=ticket(),seq=++catalogSeq;if(!current(t))return;try{const data=(await getBedSourceOptions()).data;if(!current(t)||seq!==catalogSeq)return;if(!Array.isArray(data?.departments)||data.provider_required!==false||new Set(data.departments.map(x=>x.department_id)).size!==data.departments.length||data.departments.some(d=>!bedPositive(d.department_id)))throw new Error('实际授权科室目录无法核对');departments.value=data.departments;if(props.departmentId)await departmentOptions();await load();}catch(f){if(current(t)&&seq===catalogSeq)unavailable(f.message);}}
async function departmentOptions(){const t=ticket(),seq=++optionsSeq,dep=department.value;options.value=null;if(!current(t)||!bedPositive(dep))return;try{const d=(await getBedSourceOptions({department_id:dep})).data;if(!current(t)||seq!==optionsSeq||dep!==department.value)return;if(d.department_id!==dep||d.schema_version!=='bed_source_private_v1'||typeof d.can_record!=='boolean'||!Array.isArray(d.wards)||new Set(d.wards.map(w=>w.ward_id)).size!==d.wards.length||d.wards.some(w=>!bedPositive(w.ward_id)||w.department_id!==dep)||props.wardId&&!d.wards.some(w=>w.ward_id===props.wardId))throw new Error('当前病区归属与原科室目录无法核对');options.value=d;}catch(f){if(current(t)&&seq===optionsSeq)unavailable(f.message);}}
async function load(){const t=ticket(),seq=++listSeq,key=query();items.value=[];total.value=0;error.value='';if(!current(t)||!props.governance&&(!bedPositive(department.value)||!bedPositive(ward.value)))return;loading.value=true;try{const params={...(department.value?{department_id:department.value}:{}),...(ward.value?{ward_id:ward.value}:{}),...(status.value?{status:status.value}:{}),page:page.value,page_size:20},d=(await(props.governance?getAdminBedSeries(params):getBedSeries(params))).data;if(!current(t)||seq!==listSeq||key!==query())return;if(!Array.isArray(d?.items)||!Number.isSafeInteger(d.total)||d.total<0||d.page!==page.value||d.page_size!==20||d.items.length>20||d.items.length>d.total||new Set(d.items.map(r=>r.series_id)).size!==d.items.length||d.items.some(r=>!bedSeriesMetadataValid(r,department.value||null,ward.value||null)||status.value&&r.status!==status.value))throw new Error('完整序列目录与原科室病区或治理状态不一致');items.value=d.items;total.value=d.total;}catch(f){if(current(t)&&seq===listSeq&&key===query())unavailable(f.message);}finally{if(current(t)&&seq===listSeq)loading.value=false;}}
async function preview(){if(!canRecord.value||!periodValid.value||saving.value)return;clearPreview();const t=ticket(),seq=previewSeq,input=JSON.parse(JSON.stringify(period.value)),dep=department.value;previewing.value=true;error.value='';try{const d=(await previewBedSeries(input)).data;if(!current(t)||seq!==previewSeq||supportCanonical(input)!==supportCanonical(period.value)||dep!==department.value)return;if(!await verifyBedSeriesPreview(d,input,dep))throw new Error('完整来源、床位身份、日界或集合摘要不能核对，未截断或预选');if(current(t)&&seq===previewSeq&&supportCanonical(input)===supportCanonical(period.value))candidate.value=d;}catch(f){if(current(t)&&seq===previewSeq){clearPreview();error.value=f.message||'完整来源预览失败';}}finally{if(current(t)&&seq===previewSeq)previewing.value=false;}}
async function capture(){if(!canRecord.value||!formValid.value||saving.value||!candidate.value)return;let body;try{const req=editor.value.build();if(!bedSeriesRequestValid(req,candidate.value))return;body={request:req,expected_collection_digest:candidate.value.collection_digest};}catch{return;}const t=ticket(),seq=previewSeq,dep=department.value,id=ward.value;saving.value=true;try{const row=(await createBedSeries(body)).data;if(!current(t)||seq!==previewSeq||dep!==department.value||id!==ward.value)return;if(!auditMatches(row)||!await verifyBedSeries(row,dep,id)||row.status!=='draft'||row.revision!==1||row.collection_digest!==body.expected_collection_digest||supportCanonical(row.snapshot?.request)!==supportCanonical(body.request))throw new Error('捕获回执与完整请求、原病区或全部成员不一致');if(!current(t)||seq!==previewSeq)return;clearPreview();notice.value='已捕获全部来源并保存草稿，尚未发布或运行预测。';emit('series-changed',row);await load();}catch(f){if(current(t)&&seq===previewSeq){clearPreview();error.value=f.message||'当前集合已变化，须重新读取并逐件核实';}}finally{if(current(t)&&seq===previewSeq)saving.value=false;}}
async function inspect(original){clearDetail();detailOpen.value=true;const t=ticket(),seq=detailSeq,key=query();try{const row=(await(props.governance?getAdminBedSeriesDetail(original.series_id):getBedSeriesDetail(original.series_id))).data;if(!current(t)||seq!==detailSeq||key!==query()||!detailOpen.value)return;if(!auditMatches(row)||!await verifyBedSeries(row,original.department_id,original.ward_id,{auditOnly:props.governance})||['series_id','content_hash','governance_hash','status','revision','projection_hash','collection_digest'].some(k=>row[k]!==original[k]))throw new Error('完整序列原件、公开投影或治理已变化，请重新查询');if(current(t)&&seq===detailSeq&&key===query()&&detailOpen.value)detail.value=row;}catch(f){if(current(t)&&seq===detailSeq)detailError.value=f.message||'冻结原件不能核对';}}
