async function act(action){const original=detail.value;if(!original||acting.value||!current(ticket())||(action==='revoke'?!original.can_revoke||!revokeValid.value:!canReview.value||!bedReviewBasisValid(reviewBasis.value)))return;const t=ticket(),seq=detailSeq,key=query(),body=action==='revoke'?{expected_revision:original.revision,reason:revokeReason.value}:{expected_revision:original.revision,expected_content_hash:original.content_hash,decision:action,review_basis_note:reviewBasis.value};acting.value=true;try{const row=(await(action==='revoke'?revokeBedSeries:reviewBedSeries)(original.series_id,body)).data;if(!current(t)||seq!==detailSeq||key!==query()||!detailOpen.value)return;if(!auditMatches(row)||!await verifyBedSeries(row,original.department_id,original.ward_id,{auditOnly:props.governance})||!await verifyBedSeriesTransition(row,original,action,body))throw new Error('本次治理CAS回执与完整原件或审核依据不一致');if(!current(t)||seq!==detailSeq||key!==query()||!detailOpen.value)return;detail.value=row;reviewBasis.value=revokeReason.value='';emit('series-changed',row);await load();}catch(f){if(current(t)&&seq===detailSeq){clearDetail();clearPreview();detailError.value=f.message||'当前治理授权无法核对，旧原文已清除';}}finally{if(current(t)&&seq===detailSeq)acting.value=false;}}
